export const getUpdateListingIssueUrl = (id: string,) => {




  return `/api/listing-issues/${id}`
}

/**
 * @summary Acknowledge or resolve listing issue
 */
export const updateListingIssue = async (id: string,
    updateListingIssueInput: UpdateListingIssueInput, options?: Parameters<typeof customFetch>[1]): Promise<ListingIssueDto> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<ListingIssueDto>(getUpdateListingIssueUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateListingIssueInput)
  }
);}





export const getUpdateListingIssueMutationKey = () => ['updateListingIssue'] as const;

export const getUpdateListingIssueMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateListingIssue>>, TError,UpdateListingIssueMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateListingIssue>>, TError,UpdateListingIssueMutationVariables, TContext> => {

const mutationKey = getUpdateListingIssueMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateListingIssue>>, UpdateListingIssueMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  updateListingIssue(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateListingIssueMutationResult = NonNullable<Awaited<ReturnType<typeof updateListingIssue>>>
    export type UpdateListingIssueMutationBody = BodyType<UpdateListingIssueInput>
    export type UpdateListingIssueMutationError = ErrorType<void>
    export type UpdateListingIssueMutationVariables = {id: string;data: BodyType<UpdateListingIssueInput>}

    /**
 * @summary Acknowledge or resolve listing issue
 */
export const useUpdateListingIssue = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateListingIssue>>, TError,UpdateListingIssueMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof updateListingIssue>>,
        TError,
        UpdateListingIssueMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateListingIssueMutationOptions(options));
    }

